(()=>{'use strict';const data=window.WUHAN_FLIGHT_CASES,roads=window.WUHAN_ROADS,host=document.getElementById('case');if(!data||!roads||!host)return;const legacy=document.createElement('details');legacy.className='legacy-case';const summary=document.createElement('summary');legacy.append(summary);while(host.firstChild)legacy.append(host.firstChild);host.append(legacy);const panel=document.createElement('section');panel.className='scenario-showcase';panel.innerHTML=`<div class="page-intro"><div><div class="overline">02 / WUHAN CASE STUDIES</div><h1 id="real-title"></h1><p id="real-intro"></p></div><span class="status" id="real-badge"></span></div><div class="reality-banner" id="real-warning"></div><div class="scenario-tabs" role="group"></div><div class="scenario-layout"><div class="scenario-main"><div class="scenario-map-heading"><div><div class="overline" id="real-number"></div><h2 id="real-name"></h2><p id="real-map-note"></p></div><span id="real-count"></span></div><svg id="real-map" role="img" viewBox="0 0 1024 650"></svg><div class="real-attribution">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> · <a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener">ODbL</a> · <a href="https://github.com/whuyao/GeoClaw_Claude/tree/main/data/wuhan" target="_blank" rel="noopener">GeoClaw</a></div></div><aside class="scenario-aside"><div class="overline">SELECTED MISSION</div><h2 id="real-mission-title"></h2><div id="real-mission-detail"></div></aside></div><div class="real-grid"><section class="real-card"><div class="overline">FLIGHT PLAN</div><h2 id="real-list-title"></h2><p class="real-muted" id="real-list-hint"></p><div id="real-missions"></div></section><section class="real-card"><div class="overline">FLIGHT METRICS</div><h2 id="real-charts-title"></h2><p class="real-muted" id="real-charts-note"></p><div class="real-chart-title" id="real-distance-title"></div><div id="real-distance-chart"></div><div class="real-chart-title" id="real-delay-title"></div><div id="real-delay-chart"></div></section></div><section class="real-card real-method"><div class="overline">METHOD & LIMITATIONS</div><h2 id="real-method-title"></h2><p id="real-method-text"></p><p id="real-obstacle-text"></p><p id="real-data-text"></p><a href="https://ntrs.nasa.gov/citations/20230014065" target="_blank" rel="noopener" id="real-paper"></a></section>`;host.prepend(panel);
const ns='http://www.w3.org/2000/svg',palette=['#147961','#cb6946','#416faa','#8f5794','#b88a20'],zh={nav:'案例展示',hero:'探索武汉案例',title:'武汉 · 航线协调案例',intro:'在武汉真实地图和公开地点基础上，观察多任务路线与起飞时间协调。',badge:'真实地理 · 假设任务',warning:'武汉地理底图 · 航线协调模拟',number:'案例',count:'架次',mapNote:'点击路线列表查看详细方案；底图需要联网。',list:'任务与线路',hint:'选择任务，地图突出显示相应航线。',charts:'任务数据统计',chartNote:'条形长度由本案例的逐条计算结果生成。',distance:'巡航距离（公里）',chartDelay:'等待时间：悬停及起飞延迟（秒）',method:'航线与协调方法',methodText:'本案例对真实坐标使用局部平面近似，以两点间直线作为假设巡航航线。按任务加入顺序检查起飞、巡航和下降的连续轨迹；当水平距离小于 50 米且垂直距离小于 30 米同时发生时，汉口案例任务 2 在交叉点前悬停 10 秒；其他冲突通过每次延迟起飞 10 秒协调。',obstacle:'静态避障：未接入可靠建筑轮廓、高度、真实禁飞区或动态空域，当前直线路线未检查这些障碍，也不保证航线可飞行。地图可见建筑仅为底图信息，没有进入计算。',dataText:'地铁站坐标和主干道路来自 GeoClaw 整理的 OSM 样本，来源项目标注提取于 2026 年 3 月；背景瓦片来自 OSM。数据可能不完整或过时，比例尺、坐标与航程为近似值，不用于实际飞行。',paper:'相关研究：NASA 交叉航线与起飞协调 ↗',legacy:'补充：武汉城市设施开放数据',task:'任务',from:'起点',to:'终点',coords:'坐标（经度，纬度）',altitude:'巡航高度',speed:'水平速度',vertical:'起降速度',distanceLabel:'巡航距离',time:'预计飞行时长',phase:'飞行阶段',desired:'期望出发',actual:'实际出发',arrival:'预计到达',strategy:'交叉处理',conflict:'期望时间与已排任务冲突',noConflict:'期望时间未与已排任务发生模型内冲突',delay:'顺序延迟',sec:'秒',climb:'上升',cruise:'巡航',descend:'下降',horiz:'水平',minutes:'分',mapAria:'武汉真实地图及假设航线',min:'分钟',route:'查看路线'},en={nav:'Case studies',hero:'Explore Wuhan cases',title:'Wuhan · Flight coordination',intro:'Illustrative missions using real Wuhan maps and mapped locations.',badge:'Real geography · hypothetical flights',warning:'Wuhan geographic basemap · simulated flight coordination',number:'CASE',count:'missions',mapNote:'Select a mission to highlight its route. Basemap tiles require internet.',list:'Missions and routes',hint:'Select a mission to inspect the flight plan.',charts:'Flight metrics',chartNote:'Bars are calculated from the individual mission plans.',distance:'Cruise distance (km)',chartDelay:'Waiting time: hover and departure delay (s)',method:'Planning and coordination',methodText:'This example uses a local planar approximation of real coordinates and straight lines as hypothetical cruise routes. Previously scheduled continuous climb, cruise and descent trajectories are checked in queue order. If horizontal separation is under 50 m and vertical separation under 30 m simultaneously, mission 2 in the Hankou example hovers for 10 seconds before the crossing; other conflicts are managed with 10-second departure delays.',obstacle:'Static avoidance: reliable building geometry, heights, actual no-fly zones and live airspace are not integrated. Straight routes have not been checked against these hazards and are not confirmed flyable. Buildings visible on the basemap are not used in computation.',dataText:'Metro coordinates and major roads are an OSM sample assembled by GeoClaw, which records extraction in March 2026; background tiles are from OSM. Data may be incomplete or outdated. Map scale, coordinates and distances are approximate and not for real flight.',paper:'Related research: NASA crossing routes and scheduling ↗',legacy:'Supplementary data: Wuhan facility sample',task:'Mission',from:'Start',to:'Destination',coords:'Coordinates (longitude, latitude)',altitude:'Cruise altitude',speed:'Horizontal speed',vertical:'Vertical speed',distanceLabel:'Cruise distance',time:'Flight duration',phase:'Flight phases',desired:'Requested departure',actual:'Scheduled departure',arrival:'Estimated arrival',strategy:'Conflict handling',conflict:'Requested time conflicts with scheduled missions',noConflict:'No modelled conflict with earlier missions at requested time',delay:'Sequential delay',sec:'s',climb:'Climb',cruise:'Cruise',descend:'Descent',horiz:'Horizontal',minutes:'min',mapAria:'Real Wuhan basemap and hypothetical flight routes',min:'min',route:'View route'};let caseIndex=0,missionIndex=0;const $=id=>document.getElementById(id);function point(key){return data.points[key]}function clock(offset){let x=9*3600+Math.floor(offset);return [Math.floor(x/3600),Math.floor(x%3600/60),x%60].map(v=>String(v).padStart(2,'0')).join(':')}function elem(tag,attrs,parent){let n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,String(v)));parent.appendChild(n);return n}function pixel(lon,lat,z){let n=256*2**z,x=(lon+180)/360*n,rad=lat*Math.PI/180,y=(1-Math.log(Math.tan(rad)+1/Math.cos(rad))/Math.PI)/2*n;return [x,y]}
function map(c,t){let svg=$('real-map');svg.replaceChildren();svg.setAttribute('aria-label',t.mapAria);let pts=[...new Set(c.missions.flatMap(m=>[m.start,m.end]))].map(point),z=15,xy=pts.map(p=>pixel(p[1],p[2],z)),x0=(Math.min(...xy.map(p=>p[0]))+Math.max(...xy.map(p=>p[0])))/2-512,y0=(Math.min(...xy.map(p=>p[1]))+Math.max(...xy.map(p=>p[1])))/2-325;let xyAt=(lon,lat)=>{let p=pixel(lon,lat,z);return [p[0]-x0,p[1]-y0]};elem('rect',{width:1024,height:650,fill:'#ecf0e9'},svg);for(let x=Math.floor(x0/256);x<=Math.floor((x0+1024)/256);x++)for(let y=Math.floor(y0/256);y<=Math.floor((y0+650)/256);y++){elem('image',{x:x*256-x0,y:y*256-y0,width:256,height:256,href:`https://tile.openstreetmap.org/${z}/${x}/${y}.png`},svg)}let rr=elem('g',{opacity:'.48'},svg);roads.forEach(r=>{let coords=r.coords.map(p=>xyAt(p[0],p[1]));if(!coords.some(p=>p[0]>-100&&p[0]<1124&&p[1]>-100&&p[1]<750))return;elem('polyline',{points:coords.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#a9a597','stroke-width':'2'},rr)});c.missions.forEach((m,i)=>{let a=point(m.start),b=point(m.end),pa=xyAt(a[1],a[2]),pb=xyAt(b[1],b[2]);elem('line',{x1:pa[0],y1:pa[1],x2:pb[0],y2:pb[1],stroke:'#fff','stroke-width':i===missionIndex?9:6,opacity:'.85'},svg);elem('line',{x1:pa[0],y1:pa[1],x2:pb[0],y2:pb[1],stroke:palette[i],opacity:i===missionIndex?1:.62,'stroke-width':i===missionIndex?5:3,'stroke-dasharray':i===missionIndex?'none':'7 4'},svg)});pts.forEach(p=>{let a=xyAt(p[1],p[2]);elem('circle',{cx:a[0],cy:a[1],r:7,fill:'#183d32',stroke:'#fff','stroke-width':3},svg);let n=elem('text',{x:a[0]+10,y:a[1]-10,fill:'#122d25',stroke:'#fff','stroke-width':4,'paint-order':'stroke','font-size':16,'font-weight':700},svg);n.textContent=p[0]})}
function render(){let lang=document.documentElement.lang.startsWith('en')?'en':'zh',t=lang==='zh'?zh:en,c=data.cases[caseIndex],m=c.missions[missionIndex];document.querySelector('nav a[href="#case"]').textContent=t.nav;document.querySelector('[data-t="exploreCase"]').textContent=t.hero;summary.textContent=t.legacy;for(let [id,text] of Object.entries({'real-title':t.title,'real-intro':t.intro,'real-badge':t.badge,'real-warning':t.warning,'real-number':`${t.number} 0${caseIndex+1}`,'real-name':c[lang],'real-count':`${c.missions.length} ${t.count}`,'real-map-note':t.mapNote,'real-list-title':t.list,'real-list-hint':t.hint,'real-charts-title':t.charts,'real-charts-note':t.chartNote,'real-distance-title':t.distance,'real-delay-title':t.chartDelay,'real-method-title':t.method,'real-method-text':t.methodText,'real-obstacle-text':t.obstacle,'real-data-text':t.dataText,'real-paper':t.paper,'real-mission-title':`${t.task} ${m.id} · ${point(m.start)[0]} → ${point(m.end)[0]}`}))$(id).textContent=text;let tabs=panel.querySelector('.scenario-tabs');tabs.replaceChildren();data.cases.forEach((item,i)=>{let b=document.createElement('button');b.type='button';b.textContent=`0${i+1}  ${item[lang]}`;b.classList.toggle('active',i===caseIndex);b.setAttribute('aria-pressed',String(i===caseIndex));b.addEventListener('click',()=>{caseIndex=i;missionIndex=0;render()});tabs.append(b)});let list=$('real-missions');list.replaceChildren();c.missions.forEach((f,i)=>{let btn=document.createElement('button');btn.type='button';btn.className='real-mission'+(i===missionIndex?' selected':'');btn.setAttribute('aria-pressed',String(i===missionIndex));let dot=document.createElement('i');dot.style.background=palette[i];let label=document.createElement('span');label.textContent=`${t.task} ${f.id} · ${point(f.start)[0]} → ${point(f.end)[0]}`;let detail=document.createElement('small');detail.textContent=`${(f.distance/1000).toFixed(2)} km · ${f.hover?(lang==='zh'?'悬停':'Hover')+' '+f.hover.seconds+' '+t.sec:t.delay+' '+f.delay+' '+t.sec}`;btn.append(dot,label,detail);btn.addEventListener('click',()=>{missionIndex=i;render()});list.append(btn)});let details=$('real-mission-detail');details.replaceChildren();function row(k,v){let x=document.createElement('div'),a=document.createElement('span'),b=document.createElement('strong');a.textContent=k;b.textContent=v;x.append(a,b);details.append(x)}function place(label,key){let p=point(key),x=document.createElement('div'),a=document.createElement('span'),b=document.createElement('strong'),link=document.createElement('a');a.textContent=label;b.textContent=p[0];link.href=`https://www.openstreetmap.org/node/${p[3]}`;link.target='_blank';link.rel='noopener';link.textContent=`${p[1].toFixed(6)}, ${p[2].toFixed(6)} ↗`;x.append(a,b,link);details.append(x)}place(t.from,m.start);place(t.to,m.end);row(t.altitude,`${m.height} m`);row(t.speed,`${m.speed} m/s`);row(t.vertical,`${m.verticalSpeed} m/s`);row(t.distanceLabel,`${(m.distance/1000).toFixed(2)} km`);row(t.time,`${(m.duration/60).toFixed(1)} ${t.min}`);row(t.phase,`${t.climb} ${(m.height/m.verticalSpeed).toFixed(0)} s · ${t.cruise} ${(m.distance/m.speed).toFixed(0)} s${m.hover ? (lang==='zh'?' · 悬停 ':' · Hover ')+m.hover.seconds+' s' : ''} · ${t.descend} ${(m.height/m.verticalSpeed).toFixed(0)} s`);row(t.desired,clock(m.requested));row(t.actual,clock(m.departure));row(t.arrival,clock(m.departure+m.duration));row(t.strategy,m.hover ? (lang==='zh'?`与任务 ${m.hover.conflictsWith.join(', ')} 在 ${m.height} 米高度交叉；交叉点前 ${m.hover.beforeCrossingMeters} 米悬停 ${m.hover.seconds} 秒后通过`:`Crosses mission ${m.hover.conflictsWith.join(', ')} at ${m.height} m; hover ${m.hover.seconds} s at ${m.hover.beforeCrossingMeters} m before crossing`) : m.conflicts.length?`${t.conflict} ${m.conflicts.join(', ')}；${t.delay} ${m.delay} ${t.sec}`:t.noConflict);for(const [id,key] of [['real-distance-chart','distance'],['real-delay-chart','delay']]){let box=$(id);box.replaceChildren();let measure=f=>key==='delay'?f.delay+(f.hover?.seconds||0):f[key];let max=Math.max(1,...c.missions.map(measure));c.missions.forEach((f,i)=>{let r=document.createElement('div');r.className='real-bar-row';let label=document.createElement('span');label.textContent=`${t.task} ${f.id}`;let track=document.createElement('div');track.className='real-bar-track';let bar=document.createElement('i');bar.style.width=(100*measure(f)/max)+'%';bar.style.background=palette[i];track.append(bar);let val=document.createElement('strong');val.textContent=key==='distance'?(f.distance/1000).toFixed(2):String(measure(f));r.append(label,track,val);box.append(r)})}map(c,t)}document.getElementById('language').addEventListener('click',render);render()})();

